export function buildWebAppearance(theme, language) {
  const current = MOTIFS[theme] || MOTIFS.cosmos;
  const dictionary = WEB_TRANSLATIONS[language] || {};
  // Embed CSS/text/icon data as escaped JSON to prevent breaking the JS literal.
  return `(function(){
   try {
     var css=${JSON.stringify(current.css)};
     var icons=${JSON.stringify(current.icons)};
     var dict=${JSON.stringify(dictionary)};
     var lang=${JSON.stringify(language)};
     var marker='rd-phone-theme-334';
     var style=document.getElementById(marker);
     if(!style){style=document.createElement('style');style.id=marker;(document.head||document.documentElement).appendChild(style);}
     style.textContent=css;
     document.documentElement.lang=lang;
     var replacements={
       'de':[['Świt','Sonnenaufgang'],['Dzień','Tag'],['Zmierzch','Dämmerung'],['Aktualizacje','Updates'],['Sieć:','Netz:'],['Wybierz ikonę dla','Symbol auswählen für'],['Wybierz ikonę','Symbol auswählen'],['Harmonogram','Zeitplan']],
       'en':[['Świt','Dawn'],['Dzień','Day'],['Zmierzch','Dusk'],['Aktualizacje','Updates'],['Sieć:','Network:'],['Wybierz ikonę dla','Choose icon for'],['Wybierz ikonę','Choose icon'],['Harmonogram','Schedule']]
     };
     function translate(str){
       if(!str||lang==='pl')return str;
       var trimmed=str.trim();
       if(Object.prototype.hasOwnProperty.call(dict,trimmed))return str.replace(trimmed,dict[trimmed]);
       var out=str; (replacements[lang]||[]).forEach(function(r){out=out.split(r[0]).join(r[1]);});
       return out;
     }
     function apply(){
       if(!document.body)return;
       // Original /icon/{index}.jpg remains the source of truth for ESP.
       // We only replace image pixels in this Android WebView.
       var cards=Array.from(document.querySelectorAll('#sections .card.light'));
       document.querySelectorAll('img.icoImg,.iconChoices img').forEach(function(img){
         var original=img.getAttribute('data-rd-original');
         if(!original){original=img.getAttribute('src')||'';img.setAttribute('data-rd-original',original);}
         var tail=original.split('/icon/')[1]||'';
         var id=tail.charAt(0);
         if(!'012345'.includes(id)||tail.indexOf('.jpg')!==1)return;
         var key=id;
         if(key==='0'&&cards.length>1&&cards[1].contains(img)&&!img.closest('.iconEditor'))key='light2';
         var picture=icons[key]||icons[id];
         if(img.getAttribute('data-rd-icon-key')!==key){img.src=picture;img.setAttribute('data-rd-icon-key',key);}
       });
       if(lang==='pl')return;
       var walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,null,false), node;
       while(node=walker.nextNode()){
         if(!node.parentElement||node.parentElement.closest('script,style,textarea,input,[contenteditable]'))continue;
         var translated=translate(node.nodeValue);
         if(translated!==node.nodeValue)node.nodeValue=translated;
       }
       document.querySelectorAll('[title],[placeholder],[aria-label]').forEach(function(el){
         ['title','placeholder','aria-label'].forEach(function(attr){
           var old=el.getAttribute(attr);if(old){var next=translate(old);if(next!==old)el.setAttribute(attr,next);}
         });
       });
     }
     var scheduled=false;
     function run(){if(scheduled)return;scheduled=true;requestAnimationFrame(function(){scheduled=false;apply();});}
     if(document.body){run();new MutationObserver(run).observe(document.body,{childList:true,subtree:true,characterData:true});}
     else document.addEventListener('DOMContentLoaded',function(){run();new MutationObserver(run).observe(document.body,{childList:true,subtree:true,characterData:true});},{once:true});
   }catch(err){/* In case of styling error, ESP control still works normally. */}
  })();true;`;
}
